// A small task tracker.

class Task {
  id: number;
  title: string;
  done: boolean;
  priority: number;

  constructor(id: number, title: string) {
    this.id = id;
    this.title = title;
    this.done = false;
    this.priority = 5;
  }
}

function find(tasks: Task[], id: number): Task | undefined {
  return tasks.find((task) => task.id == id);
}

// Tasks ordered by priority ascending, ties broken by id ascending.
function ordered(tasks: Task[]): Task[] {
  return [...tasks].sort((a, b) => a.priority - b.priority || a.id - b.id);
}

function main() {
  const text = Deno.readTextFileSync(Deno.args[0]);
  const tasks: Task[] = [];
  let next_id = 1;

  for (const line of text.replace(/\n+$/, "").split("\n")) {
    if (line.trim() == "") {
      continue;
    }
    const space = line.indexOf(" ");
    const command = space < 0 ? line : line.slice(0, space);
    const rest = space < 0 ? "" : line.slice(space + 1);

    if (command == "add") {
      tasks.push(new Task(next_id, rest));
      console.log(`added ${next_id}`);
      next_id = next_id + 1;
    } else if (command == "done") {
      const id = Number(rest);
      const task = find(tasks, id);
      if (task === undefined) {
        console.log(`no such task ${id}`);
      } else {
        task.done = true;
        console.log(`done ${id}`);
      }
    } else if (command == "prio") {
      const sep = rest.indexOf(" ");
      const id = Number(sep < 0 ? rest : rest.slice(0, sep));
      const p = sep < 0 ? "" : rest.slice(sep + 1);
      const task = find(tasks, id);
      if (task === undefined) {
        console.log(`no such task ${id}`);
      } else if (!/^[0-9]$/.test(p)) {
        console.log(`bad priority ${p}`);
      } else {
        task.priority = Number(p);
        console.log(`prio ${id} ${p}`);
      }
    } else if (command == "list") {
      if (rest == "all") {
        for (const task of ordered(tasks)) {
          const mark = task.done ? "x" : "-";
          console.log(`${mark} ${task.id} ${task.title}`);
        }
      } else {
        for (const task of ordered(tasks)) {
          if (!task.done) {
            console.log(`${task.id} ${task.title}`);
          }
        }
      }
    } else {
      console.log(`? ${command}`);
    }
  }
}

main();

